<script setup lang="ts">
import {ref,computed,onMounted,watch,nextTick} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import BaseCard from '@/components/BaseCard.vue';import AppButton from '@/components/AppButton.vue';import BottomActionBar from '@/components/BottomActionBar.vue';import StepProgress from '@/components/StepProgress.vue';import StatusTag from '@/components/StatusTag.vue';import SectionHeader from '@/components/SectionHeader.vue'
import Stage1Field from './Stage1Field.vue';import Stage1Region from './Stage1Region.vue';import Stage1Status from './Stage1Status.vue';import QualificationForm from './QualificationForm.vue'
import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label} from '../../services/stage1';import type {Data} from '../../services/stage1'
const props=defineProps<{change?:boolean;query?:Data}>()
const p=useStage1Page(props.change?'profile-change':'application'),{error,busy,loading,pending,dirty}=p
const record=ref<Data|null>(null),profile=ref<Data|null>(null),form=ref<Data>({qualifications:[],categoryIds:[]}),options=ref<Data>({categories:[],qualificationTypes:[]}),step=ref(1)
let replacing=false,initialized=false
const editable=computed(()=>!record.value||['DRAFT','REJECTED'].includes(record.value.status)),disabled=computed(()=>!editable.value||busy.value||pending.value||props.change&&!p.has('profile.write'))
watch(form,()=>{if(!replacing)dirty.value=true},{deep:true})
function profilePayload(value:Data){return {...value.extra,storeName:value.storeName,legalName:value.legalName,legalCode:value.legalCode,legalPerson:value.legalPerson,contactName:value.contactName,phone:value.phone,address:value.address,description:value.description,categoryIds:value.categoryIds,qualifications:value.qualifications.versions.filter((q:Data)=>q.status==='APPROVED').map((q:Data)=>q.details)}}
function load(){return p.read(async()=>{const opts=await stage1Service.options();const current=props.change?await stage1Service.read<Data|null>('/profile-change/current'):await stage1Service.application();const store=props.change?await stage1Service.profile():null;return {opts,current,store}},value=>{replacing=true;options.value=value.opts;record.value=value.current;profile.value=value.store;form.value={qualifications:[],categoryIds:[],...JSON.parse(JSON.stringify(value.current?.payload||value.store&&profilePayload(value.store)||{}))};dirty.value=false;initialized=true;void nextTick(()=>{replacing=false})})}
function payload(value:Data):Data{const result:Data={};Object.entries(value).forEach(([key,item])=>{if(item!==''&&item!==undefined)result[key]=Array.isArray(item)?item.map(v=>v&&typeof v==='object'?payload(v):v):item&&typeof item==='object'?payload(item):item});return result}
async function accept(value:Data){record.value=value;dirty.value=false;await load()}
async function save(){await p.write(()=>p.command<Data>(record.value?'/application/'+record.value.id+'/draft':'/application',{...(record.value?{expectedVersion:record.value.version}:{}),payload:payload(form.value)},record.value?'PUT':'POST'),value=>{record.value=value;dirty.value=false})}
async function submit(){const confirm=await uni.showModal({title:props.change?'提交资料变更审核？':'提交入驻审核？',content:'提交后当前版本将锁定，审核结果以平台反馈为准。'});if(!confirm.confirm)return;if(props.change){await p.write(()=>p.command<Data>('/profile-change/submit',{expectedVersion:profile.value?.version,payload:payload(form.value)}),value=>{record.value=value;dirty.value=false});return}if(dirty.value||!record.value)await save();if(dirty.value||!record.value||pending.value||error.value)return;await p.write(()=>p.command<Data>('/application/'+record.value!.id+'/submit',{expectedVersion:record.value!.version}),value=>{record.value=value;dirty.value=false})}
function addQualification(){form.value.qualifications.push({type:'BUSINESS_LICENSE',fileIds:[],categoryIds:[],longTerm:false})}
onMounted(load);onShow(()=>{if(initialized&&!dirty.value&&!pending.value)void load()})
</script>
<template><AppPage secondary with-bottom-action :status="loading&&!initialized?'loading':'ready'" :state-message="error" @retry="load"><template #navbar><AppNavbar :title="change?'主体资料变更':'商户入驻申请'" centered show-back/></template><view class="s1-application stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(accept)" @retry="p.retry(accept)" @abandon="p.abandon(accept)"/><BaseCard><SectionHeader :title="record?label(record.status):'申请草稿'"/><text class="s1-copy">{{change?'当前批准资料继续生效，审核通过后更新。':'入驻批准前保持申请人身份；批准后需要重新微信登录取得可信店铺身份。'}}</text><StatusTag v-if="record" :tone="record.status==='REJECTED'?'error':record.status==='APPROVED'?'success':'pending'">版本 {{record.revision}} · {{label(record.status)}}</StatusTag><view v-for="item in record?.history||[]" :key="item.revision" class="s1-history"><text>提交版本 {{item.revision}} · {{label(item.status)}}</text><text v-if="item.reason">{{item.reason}}</text><text>{{item.reviewedAt||item.submittedAt}}</text></view></BaseCard><StepProgress :steps="['主体','联系与范围','资质','确认']" :current="step" @select="!busy&&!pending&&(step=$event)"/><BaseCard v-if="step===1" class="s1-form"><SectionHeader title="经营主体"/><Stage1Field v-model="form.subjectType" label="主体类型" type="select" :options="[{value:'INDIVIDUAL_BUSINESS',label:'个体工商户'},{value:'ENTERPRISE',label:'企业'}]" :disabled="disabled" required/><Stage1Field v-model="form.legalName" label="主体名称" :disabled="disabled" :maximum="100" required/><Stage1Field v-model="form.legalCode" label="统一社会信用代码" :disabled="disabled||change" :maximum="18" required/><Stage1Field v-model="form.legalPerson" label="经营者 / 法定代表人" :disabled="disabled" :maximum="50" required/><Stage1Field v-model="form.storeName" label="店铺名称" :disabled="disabled" :maximum="30" required/></BaseCard><BaseCard v-if="step===2" class="s1-form"><SectionHeader title="联系、地址与类目"/><Stage1Field v-model="form.contactName" label="联系人" :disabled="disabled" :maximum="30" required/><Stage1Field v-model="form.phone" label="联系电话" :disabled="disabled" :maximum="20" required/><Stage1Region v-model="form" :disabled="disabled"/><Stage1Field v-model="form.address" label="详细地址" :disabled="disabled" :maximum="200" required/><Stage1Field v-model="form.businessHours" label="营业时间" :disabled="disabled" :maximum="200"/><Stage1Field v-model="form.description" label="店铺介绍" type="textarea" :disabled="disabled" :maximum="500"/><Stage1Field v-model="form.categoryIds" label="申请经营类目" type="multi" :options="options.categories.map((c:any)=>({value:c.id,label:c.name}))" :disabled="disabled" required/></BaseCard><view v-if="step===3" class="stack"><BaseCard v-for="(q,index) in form.qualifications" :key="index" class="s1-form"><SectionHeader :title="'资质 '+(index+1)"/><QualificationForm v-model="form.qualifications[index]" :receipt-key="'application_qualification_'+index" :types="options.qualificationTypes" :categories="options.categories" :disabled="disabled"/><AppButton variant="quiet" :disabled="disabled" @click="form.qualifications.splice(index,1)">移除此项</AppButton></BaseCard><AppButton v-if="!disabled" variant="secondary" @click="addQualification">增加资质</AppButton></view><BaseCard v-if="step===4" class="s1-form"><SectionHeader title="确认本次资料"/><text>{{form.storeName||'店铺名称未填写'}}</text><text>{{form.legalName||'主体名称未填写'}}</text><text>经营范围 {{form.categoryIds.length}} 项 · 资质 {{form.qualifications.length}} 项</text><text class="s1-copy">请逐步核对主体、范围、证照有效期和附件。提交后以本次快照进行审核；协议确认独立办理。</text><AppButton v-if="!editable" variant="secondary" @click="load">重新读取审核结果</AppButton></BaseCard><view class="s1-steps"><AppButton v-if="step>1" variant="quiet" @click="step--">上一步</AppButton><AppButton v-if="step<4" variant="secondary" @click="step++">下一步</AppButton></view><BottomActionBar v-if="editable"><AppButton v-if="!change" variant="secondary" :disabled="disabled" :loading="busy" @click="save">保存草稿</AppButton><AppButton :disabled="disabled||step!==4" :loading="busy" @click="submit">提交审核</AppButton></BottomActionBar></view></AppPage></template>
<style scoped lang="scss">.s1-application{padding:$space-4 $page-gutter}.s1-form{display:flex;flex-direction:column;gap:$space-4}.s1-copy{display:block;color:$color-text-secondary;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-history{display:flex;flex-direction:column;gap:$space-1;margin-top:$space-3;padding-top:$space-3;border-top:1px solid $color-border;font-size:14px;line-height:1.6}.s1-steps{display:flex;gap:$space-3}.s1-steps>*{flex:1}:deep(.app-button){height:auto;min-height:$touch-target-min;line-height:1.5;padding-top:$space-3;padding-bottom:$space-3}</style>
